import{_ as d,o as e,c as r,a4 as n}from"./chunks/framework.BMj-uaUw.js";const s=JSON.parse('{"title":"术语表","description":"","frontmatter":{},"headers":[{"level":2,"title":"一、工程化与工具链","slug":"一、工程化与工具链","link":"#一、工程化与工具链","children":[]},{"level":2,"title":"二、模块与依赖","slug":"二、模块与依赖","link":"#二、模块与依赖","children":[]},{"level":2,"title":"三、Vue 核心概念","slug":"三、vue-核心概念","link":"#三、vue-核心概念","children":[]},{"level":2,"title":"四、组件通信与复用","slug":"四、组件通信与复用","link":"#四、组件通信与复用","children":[]},{"level":2,"title":"五、路由与应用架构","slug":"五、路由与应用架构","link":"#五、路由与应用架构","children":[]},{"level":2,"title":"六、网络与部署","slug":"六、网络与部署","link":"#六、网络与部署","children":[]},{"level":2,"title":"七、质量与协作","slug":"七、质量与协作","link":"#七、质量与协作","children":[]},{"level":2,"title":"八、常见\\"看起来像\\"的概念对照","slug":"八、常见-看起来像-的概念对照","link":"#八、常见-看起来像-的概念对照","children":[]},{"level":2,"title":"九、跨端与小程序","slug":"九、跨端与小程序","link":"#九、跨端与小程序","children":[]},{"level":2,"title":"十、AI 协作","slug":"十、ai-协作","link":"#十、ai-协作","children":[{"level":3,"title":"两对容易混的","slug":"两对容易混的","link":"#两对容易混的","children":[]}]}],"relativePath":"appendix/glossary.md","filePath":"appendix/glossary.md","lastUpdated":1789500889000}'),o={name:"appendix/glossary.md"};function i(a,t,c,u,h,l){return e(),r("div",null,[...t[0]||(t[0]=[n('<h1 id="术语表" tabindex="-1">术语表 <a class="header-anchor" href="#术语表" aria-label="Permalink to &quot;术语表&quot;">​</a></h1><p>收录 80 条以上容易混淆或经常出现的术语。<strong>按四栏写：术语（中英）、一句话解释、常见误解、在本课程哪一节出现。</strong></p><p>读英文文档被术语卡住时，先在这里找一遍，再回去读原文。</p><h2 id="一、工程化与工具链" tabindex="-1">一、工程化与工具链 <a class="header-anchor" href="#一、工程化与工具链" aria-label="Permalink to &quot;一、工程化与工具链&quot;">​</a></h2><table tabindex="0"><thead><tr><th>术语（中英）</th><th>一句话解释</th><th>常见误解</th><th>出现位置</th></tr></thead><tbody><tr><td>工程化 Frontend Engineering</td><td>把&quot;一个人写页面&quot;变成&quot;一套可维护、可协作、可交付的流程&quot;</td><td>以为用了框架就是工程化</td><td><a href="/frontend-engineering-course/unit01/01-why-engineering.html">1.1</a></td></tr><tr><td>构建工具 Build Tool</td><td>把源码加工成浏览器能直接运行的产物的工具</td><td>以为构建工具就是&quot;打包器&quot;</td><td><a href="/frontend-engineering-course/unit02/04-vite.html">2.4</a></td></tr><tr><td>打包 Bundling</td><td>把分散的模块合并成少量文件，减少请求数</td><td><strong>以为打包就是压缩</strong>。压缩只是打包过程中的一步，打包的核心是&quot;合并模块、处理依赖关系&quot;</td><td><a href="/frontend-engineering-course/unit02/04-vite.html">2.4</a></td></tr><tr><td>编译 Compile</td><td>把一种语言写成另一种语言的等价形式</td><td>以为前端没有编译。把 <code>.vue</code> 转成 JS 就是编译</td><td><a href="/frontend-engineering-course/unit02/04-vite.html">2.4</a></td></tr><tr><td>转译 Transpile</td><td>把同一门语言的高版本语法转成低版本语法</td><td><strong>和编译混为一谈</strong>。转译是&quot;同语言换版本&quot;，编译是&quot;换语言&quot;</td><td><a href="/frontend-engineering-course/unit02/01-node.html">2.1</a></td></tr><tr><td>产物 Build Output</td><td><code>build</code> 之后生成的、能直接部署的文件</td><td>以为 <code>dist/</code> 可以手改</td><td><a href="/frontend-engineering-course/unit02/04-vite.html">2.4</a></td></tr><tr><td>热更新 HMR</td><td>改代码后只替换改动的那部分，页面不整页刷新且保留状态</td><td>以为热更新就是&quot;自动刷新页面&quot;。整页刷新会丢表单内容，热更新不会</td><td><a href="/frontend-engineering-course/unit02/04-vite.html">2.4</a></td></tr><tr><td>预构建 Pre-bundling</td><td>Vite 启动时先把第三方依赖预处理成 ESM，加快开发响应</td><td>以为预构建是&quot;生产构建的预演&quot;。它只服务于开发服务器</td><td><a href="/frontend-engineering-course/unit02/04-vite.html">2.4</a></td></tr><tr><td>脚手架 Scaffold</td><td>一条命令生成项目骨架的工具</td><td>以为脚手架生成的东西不能改</td><td><a href="/frontend-engineering-course/unit11/02-scaffold.html">11.2</a></td></tr><tr><td>环境变量 Environment Variable</td><td>同一份代码在不同环境读到的不同配置值</td><td>以为随便起个名字就能读到。只有 <code>VITE_</code> 开头的才会暴露给浏览器</td><td><a href="/frontend-engineering-course/unit02/05-env-config.html">2.5</a></td></tr></tbody></table><h2 id="二、模块与依赖" tabindex="-1">二、模块与依赖 <a class="header-anchor" href="#二、模块与依赖" aria-label="Permalink to &quot;二、模块与依赖&quot;">​</a></h2><table tabindex="0"><thead><tr><th>术语（中英）</th><th>一句话解释</th><th>常见误解</th><th>出现位置</th></tr></thead><tbody><tr><td>模块化 Modularity</td><td>把代码拆成职责单一、可单独引用的文件</td><td>以为&quot;文件多&quot;就是模块化好。关键是职责边界清晰</td><td><a href="/frontend-engineering-course/unit03/03-modules-structure.html">3.3</a></td></tr><tr><td>ESM</td><td>JavaScript 官方的模块标准，用 <code>import</code> / <code>export</code></td><td>以为所有浏览器的 <code>import</code> 行为都一样（实际由构建工具处理）</td><td><a href="/frontend-engineering-course/unit02/03-package-json.html">2.3</a></td></tr><tr><td>CJS</td><td>Node 早期的模块标准，用 <code>require</code> / <code>module.exports</code></td><td>以为 CJS 已经不能用了。很多 Node 工具链仍在使用</td><td><a href="/frontend-engineering-course/unit02/03-package-json.html">2.3</a></td></tr><tr><td>依赖 Dependency</td><td>项目运行或构建时需要的外部代码包</td><td>以为依赖越多越好，&quot;能用库就不自己写&quot;</td><td><a href="/frontend-engineering-course/unit02/02-package-manager.html">2.2</a></td></tr><tr><td>开发依赖 devDependency</td><td>只在开发阶段用的包，不进最终产物</td><td><strong>以为 <code>-D</code> 装的是&quot;不重要的包&quot;</strong>。区分标准是&quot;运行时代码需不需要它&quot;</td><td><a href="/frontend-engineering-course/unit02/03-package-json.html">2.3</a></td></tr><tr><td>锁文件 Lockfile</td><td>记录每个依赖确切版本的文件，保证任何人装到一样的版本</td><td>以为锁文件冲突时可以删掉重来。删掉等于放弃版本可复现性</td><td><a href="/frontend-engineering-course/unit02/02-package-manager.html">2.2</a></td></tr><tr><td>语义化版本 SemVer</td><td>用主版本.次版本.修订号描述版本，并约定升级含义</td><td>以为 <code>^3.5.42</code> 会锁死在 3.5.42。它允许同主版本内升级</td><td><a href="/frontend-engineering-course/unit02/02-package-manager.html">2.2</a></td></tr><tr><td>幽灵依赖 Phantom Dependency</td><td>代码里用了一个自己没声明、靠别人的依赖被&quot;提上来&quot;的包</td><td>以为&quot;能 import 就说明能一直用&quot;。换个包管理器立刻报错</td><td><a href="/frontend-engineering-course/unit02/02-package-manager.html">2.2</a></td></tr><tr><td>扁平化 node_modules</td><td>把依赖尽量提升到顶层，减少重复安装</td><td>以为它只有好处。它也是幽灵依赖的根源</td><td><a href="/frontend-engineering-course/unit02/02-package-manager.html">2.2</a></td></tr><tr><td>路径别名 Path Alias</td><td>用 <code>@</code> 之类的短名前缀代替长相对路径</td><td>以为配了别名就不用管大小写。别名不解决大小写问题</td><td><a href="/frontend-engineering-course/unit02/04-vite.html">2.4</a></td></tr></tbody></table><h2 id="三、vue-核心概念" tabindex="-1">三、Vue 核心概念 <a class="header-anchor" href="#三、vue-核心概念" aria-label="Permalink to &quot;三、Vue 核心概念&quot;">​</a></h2><table tabindex="0"><thead><tr><th>术语（中英）</th><th>一句话解释</th><th>常见误解</th><th>出现位置</th></tr></thead><tbody><tr><td>单文件组件 SFC</td><td>把一个组件的模板、逻辑、样式写在同一个 <code>.vue</code> 文件里</td><td>以为 <code>.vue</code> 是浏览器直接支持的文件格式，其实要经过构建处理</td><td><a href="/frontend-engineering-course/unit07/01-sfc.html">7.1</a></td></tr><tr><td>模板编译 Template Compilation</td><td>Vite 编译期把 <code>&lt;template&gt;</code> 转成渲染函数</td><td>以为模板是运行时解析的字符串</td><td><a href="/frontend-engineering-course/unit04/01-declarative.html">4.1</a></td></tr><tr><td>声明式渲染 Declarative Rendering</td><td>描述&quot;界面应该长什么样&quot;，由框架负责更新 DOM</td><td>以为声明式就不用管性能。该用 <code>key</code>、该做分割还是要做</td><td><a href="/frontend-engineering-course/unit04/01-declarative.html">4.1</a></td></tr><tr><td>虚拟 DOM Virtual DOM</td><td>用 JS 对象描述真实 DOM，对比差异后批量更新</td><td><strong>以为虚拟 DOM 一定比直接操作 DOM 快</strong>。它的价值在于&quot;让开发者不用手动管更新&quot;</td><td><a href="/frontend-engineering-course/unit04/05-reactivity-principle.html">4.5</a></td></tr><tr><td>响应式 Reactivity</td><td>数据变化时，用到它的界面和计算自动更新</td><td>以为只要赋值就会自动更新。解构、丢引用都会切断响应式</td><td><a href="/frontend-engineering-course/unit04/04-reactivity.html">4.4</a></td></tr><tr><td>依赖收集 Dependency Tracking</td><td>读取响应式数据时记录&quot;谁用了它&quot;，变化时通知这些使用者</td><td>以为依赖收集发生在赋值时。它发生在<strong>读取</strong>时</td><td><a href="/frontend-engineering-course/unit04/05-reactivity-principle.html">4.5</a></td></tr><tr><td>副作用 Side Effect</td><td>状态变化后要做的、对外部有影响的事情</td><td>以为发请求、写日志都不算副作用。它们正是<code>watch</code> 的目标</td><td><a href="/frontend-engineering-course/unit05/02-watch.html">5.2</a></td></tr><tr><td>计算属性 Computed</td><td>由已有状态算出来的值，结果被缓存</td><td><strong>以为 <code>computed</code> 和函数一样每次调用都执行</strong>。依赖不变时它直接返回缓存</td><td><a href="/frontend-engineering-course/unit05/01-computed.html">5.1</a></td></tr><tr><td>侦听器 Watcher</td><td>监听状态变化后执行一段逻辑</td><td>以为 <code>watch</code> 能替代 <code>computed</code>。<code>computed</code> 是算值，<code>watch</code> 是做事</td><td><a href="/frontend-engineering-course/unit05/02-watch.html">5.2</a></td></tr><tr><td>生命周期 Lifecycle</td><td>组件从创建到销毁经历的一系列阶段</td><td>以为钩子越多越好。大多数组件只需要 <code>onMounted</code> 和 <code>onBeforeUnmount</code></td><td><a href="/frontend-engineering-course/unit06/05-lifecycle.html">6.5</a></td></tr><tr><td>组合式 API</td><td>用 <code>ref</code>、<code>computed</code>、函数组织组件逻辑的写法</td><td>以为组合式 API 就是&quot;写得更高级&quot;。它的核心价值是<strong>逻辑可以复用</strong></td><td><a href="/frontend-engineering-course/unit04/04-reactivity.html">4.4</a></td></tr><tr><td>选项式 API</td><td>用 <code>data</code>、<code>methods</code>、<code>computed</code> 分块组织组件逻辑</td><td>以为新项目不该用。老项目还在用，能看懂是基本要求</td><td><a href="/frontend-engineering-course/unit04/04-reactivity.html">4.4</a></td></tr><tr><td>作用域样式 Scoped CSS</td><td>让组件样式只作用于当前组件</td><td>以为加了 <code>scoped</code> 就绝不会影响外部。深度选择器和全局样式仍会穿透</td><td><a href="/frontend-engineering-course/unit07/01-sfc.html">7.1</a></td></tr><tr><td>四态 Four States</td><td>加载中、出错、空数据、有数据 —— 数据页面的四种必须状态</td><td>以为写完&quot;有数据&quot;就够了。漏掉错误态会让用户看到白屏</td><td><a href="/frontend-engineering-course/unit05/05-four-states.html">5.5</a></td></tr><tr><td>内存泄漏 Memory Leak</td><td>组件卸载后，定时器/监听器仍持有引用导致资源不释放</td><td>以为页面切换会自动清理一切。定时器和手动监听必须自己清</td><td><a href="/frontend-engineering-course/unit06/05-lifecycle.html">6.5</a></td></tr></tbody></table><h2 id="四、组件通信与复用" tabindex="-1">四、组件通信与复用 <a class="header-anchor" href="#四、组件通信与复用" aria-label="Permalink to &quot;四、组件通信与复用&quot;">​</a></h2><table tabindex="0"><thead><tr><th>术语（中英）</th><th>一句话解释</th><th>常见误解</th><th>出现位置</th></tr></thead><tbody><tr><td>属性 Props</td><td>父组件传给子组件的数据，子组件只读</td><td><strong>以为子组件也能直接改 <code>props</code></strong>。改了会报&quot;target is readonly&quot;</td><td><a href="/frontend-engineering-course/unit07/02-props.html">7.2</a></td></tr><tr><td>事件 Emits</td><td>子组件通知父组件发生了什么事，可携带数据</td><td>以为 <code>emit</code> 是&quot;改父组件的数据&quot;。它只是通知，改不改由父组件决定</td><td><a href="/frontend-engineering-course/unit07/03-emits.html">7.3</a></td></tr><tr><td>插槽 Slot</td><td>父组件往子组件的指定位置填内容</td><td>以为插槽只是&quot;传 HTML&quot;。它让组件有了可定制的结构</td><td><a href="/frontend-engineering-course/unit08/01-slots.html">8.1</a></td></tr><tr><td>作用域插槽 Scoped Slot</td><td>子组件把数据&quot;给回&quot;父组件，让父组件决定怎么渲染</td><td>以为作用域插槽就是普通插槽加参数。它是<strong>反向的数据传递</strong></td><td><a href="/frontend-engineering-course/unit08/01-slots.html">8.1</a></td></tr><tr><td>依赖注入 Dependency Injection</td><td>祖先组件提供数据，任意后代组件都能直接获取</td><td>以为它能当全局状态用。它只在当前组件树存活期内有效</td><td><a href="/frontend-engineering-course/unit08/02-provide-inject.html">8.2</a></td></tr><tr><td>组合式函数 Composable</td><td>用函数封装可复用的有状态逻辑，名字以 <code>use</code> 开头</td><td>以为组合式函数就是普通工具函数。它<strong>内部有响应式状态</strong></td><td><a href="/frontend-engineering-course/unit08/04-composables.html">8.4</a></td></tr><tr><td>自定义指令 Custom Directive</td><td>把&quot;操作 DOM&quot;的逻辑封装成 <code>v-xxx</code> 指令</td><td>以为能自定义指令就很厉害。能用组件解决就优先用组件</td><td><a href="/frontend-engineering-course/unit08/05-directives.html">8.5</a></td></tr><tr><td>传送门 Teleport</td><td>把组件内容渲染到 DOM 树的另一个位置</td><td>以为 <code>Teleport</code> 会改变组件的父子关系。它只改渲染位置，不改逻辑关系</td><td><a href="/frontend-engineering-course/unit08/03-builtin.html">8.3</a></td></tr><tr><td>透传属性 Fallthrough Attributes</td><td>没被声明为 <code>props</code> 的属性会自动落到组件根元素上</td><td>以为所有属性都需要在 <code>props</code> 里声明</td><td><a href="/frontend-engineering-course/unit07/02-props.html">7.2</a></td></tr><tr><td>递归组件 Recursive Component</td><td>组件在自己的模板里引用自己，用来渲染树形结构</td><td>以为递归组件不用设结束条件。必须有终止分支，否则栈溢出</td><td><a href="/frontend-engineering-course/unit07/05-case-tree.html">7.5</a></td></tr></tbody></table><h2 id="五、路由与应用架构" tabindex="-1">五、路由与应用架构 <a class="header-anchor" href="#五、路由与应用架构" aria-label="Permalink to &quot;五、路由与应用架构&quot;">​</a></h2><table tabindex="0"><thead><tr><th>术语（中英）</th><th>一句话解释</th><th>常见误解</th><th>出现位置</th></tr></thead><tbody><tr><td>单页应用 SPA</td><td>只加载一个 HTML，页面切换由 JS 完成，不整页刷新</td><td><strong>以为单页应用&quot;只有一个页面&quot;</strong>。它是有很多视图，但共用一次加载</td><td><a href="/frontend-engineering-course/unit09/01-router-basics.html">9.1</a></td></tr><tr><td>路由 Routing</td><td>地址与页面之间的映射关系</td><td>以为路由只用来跳转。它还承担参数解析、权限判断</td><td><a href="/frontend-engineering-course/unit09/01-router-basics.html">9.1</a></td></tr><tr><td>动态路由参数 Dynamic Params</td><td>路径里的可变部分，如 <code>/activity/:id</code></td><td>以为 <code>params</code> 和 <code>query</code> 可以互换。前者是路径的一部分，后者是查询串</td><td><a href="/frontend-engineering-course/unit09/02-nested-params.html">9.2</a></td></tr><tr><td>嵌套路由 Nested Route</td><td>子页面渲染在父页面的 <code>&lt;RouterView /&gt;</code> 位置</td><td>以为配了 <code>children</code> 就自动生效。父组件忘了写 <code>&lt;RouterView /&gt;</code> 就不显示</td><td><a href="/frontend-engineering-course/unit09/02-nested-params.html">9.2</a></td></tr><tr><td>路由守卫 Navigation Guard</td><td>在跳转前后执行的检查逻辑</td><td>以为守卫能&quot;阻止所有非法访问&quot;。它只挡前端，真正的权限还得后端管</td><td><a href="/frontend-engineering-course/unit09/03-guards.html">9.3</a></td></tr><tr><td>状态管理 State Management</td><td>把多个页面共享的数据集中存放和管理</td><td><strong>以为所有状态都该放全局</strong>。表单草稿、弹窗开关都不该放</td><td><a href="/frontend-engineering-course/unit10/01-when-global.html">10.1</a></td></tr><tr><td>持久化 Persistence</td><td>把状态写进 <code>localStorage</code> 等存储，刷新后能恢复</td><td>以为持久化就是&quot;把整个 store 存下来&quot;。加载态、错误信息不该存</td><td><a href="/frontend-engineering-course/unit10/03-persist.html">10.3</a></td></tr><tr><td>拦截器 Interceptor</td><td>在请求发出前或响应回来后统一执行的处理逻辑</td><td>以为拦截器越复杂越好。它只该做通用的事，业务逻辑放页面</td><td><a href="/frontend-engineering-course/unit10/04-request-layer.html">10.4</a></td></tr><tr><td>幂等 Idempotent</td><td>同一个请求执行多次，对服务器的影响和执行一次相同</td><td>以为&quot;重复请求&quot;都可以自动重试。创建类接口重试可能造出重复数据</td><td><a href="/frontend-engineering-course/unit10/05-error-handling.html">10.5</a></td></tr><tr><td>请求竞态 Race Condition</td><td>先发出的请求后返回，覆盖了后发出请求的结果</td><td>以为网络快就不会遇到。快速切页时非常容易复现</td><td><a href="/frontend-engineering-course/unit10/06-case-fetch.html">10.6</a></td></tr><tr><td>请求去重 Request Deduplication</td><td>避免同一份数据被重复请求或重复追加</td><td>以为&quot;去重&quot;是后端的事。分页追加时的重复必须前端也防一道</td><td><a href="/frontend-engineering-course/unit10/06-case-fetch.html">10.6</a></td></tr></tbody></table><h2 id="六、网络与部署" tabindex="-1">六、网络与部署 <a class="header-anchor" href="#六、网络与部署" aria-label="Permalink to &quot;六、网络与部署&quot;">​</a></h2><table tabindex="0"><thead><tr><th>术语（中英）</th><th>一句话解释</th><th>常见误解</th><th>出现位置</th></tr></thead><tbody><tr><td>跨域 CORS</td><td>浏览器的同源策略限制，不同源之间请求需要服务器允许</td><td><strong>以为跨域是前端 bug</strong>。它是浏览器的安全机制，解决要靠服务端或代理</td><td><a href="/frontend-engineering-course/unit12/01-integration.html">12.1</a></td></tr><tr><td>代理 Proxy</td><td>开发服务器把请求转发给后端，绕开浏览器跨域限制</td><td>以为代理在生产环境也有效。它只服务于开发服务器</td><td><a href="/frontend-engineering-course/unit12/01-integration.html">12.1</a></td></tr><tr><td>同源 Same Origin</td><td>协议、域名、端口三者完全相同</td><td>以为同一个域名就是同源。端口不同也不算</td><td><a href="/frontend-engineering-course/unit12/01-integration.html">12.1</a></td></tr><tr><td>代码分割 Code Splitting</td><td>把产物拆成多个文件，按需加载</td><td>以为拆得越细越好。拆太细会增加请求数和管理成本</td><td><a href="/frontend-engineering-course/unit12/02-build-optimize.html">12.2</a></td></tr><tr><td>懒加载 Lazy Loading</td><td>用到某个模块时才去加载它</td><td>以为懒加载一定更快。首屏不需要的才懒加载，首屏要用的反而更慢</td><td><a href="/frontend-engineering-course/unit12/02-build-optimize.html">12.2</a></td></tr><tr><td>树摇 Tree Shaking</td><td>构建时去掉没被用到的代码</td><td>以为只要用了打包工具就自动生效。它依赖 ESM 的静态结构，CJS 效果差很多</td><td><a href="/frontend-engineering-course/unit12/02-build-optimize.html">12.2</a></td></tr><tr><td>异步组件 Async Component</td><td>把组件定义成&quot;用到时才加载&quot;</td><td>以为异步组件适合所有组件。频繁切换的组件异步化反而会闪烁</td><td><a href="/frontend-engineering-course/unit12/02-build-optimize.html">12.2</a></td></tr><tr><td>首屏 First Screen</td><td>用户打开页面到看到主要内容的时间</td><td>以为首屏快慢只跟网速有关。代码体积、请求数量、渲染阻塞都影响</td><td><a href="/frontend-engineering-course/unit12/02-build-optimize.html">12.2</a></td></tr><tr><td>白屏 Blank Screen</td><td>页面加载出来却什么都没有</td><td>以为白屏是&quot;网慢&quot;。多数是 JS 报错或资源 404</td><td><a href="/frontend-engineering-course/unit12/03-deploy.html">12.3</a></td></tr><tr><td>CSR</td><td>客户端渲染，页面内容由浏览器里的 JS 生成</td><td>以为 CSR 就是&quot;没有 SEO&quot;。现在的搜索引擎对 CSR 也有一定支持</td><td><a href="/frontend-engineering-course/unit12/02-build-optimize.html">12.2</a></td></tr><tr><td>SSR</td><td>服务端渲染，服务器直接返回带内容的 HTML</td><td>以为 SSR 一定比 CSR 快。它首屏更快，但服务器压力更大、开发更复杂</td><td><a href="/frontend-engineering-course/unit12/02-build-optimize.html">12.2</a></td></tr><tr><td>预渲染 Prerendering</td><td>构建时把特定页面提前生成静态 HTML</td><td>以为预渲染能替代 SSR。它只适合内容相对固定的少数页面</td><td><a href="/frontend-engineering-course/unit12/02-build-optimize.html">12.2</a></td></tr><tr><td>水合 Hydration</td><td>服务端渲染的静态 HTML 在浏览器里&quot;接管&quot;为可交互应用</td><td>以为水合不花钱。它要重新执行一遍 JS，可能造成短暂不可交互</td><td><a href="/frontend-engineering-course/unit12/02-build-optimize.html">12.2</a></td></tr><tr><td>环境配置文件 .env</td><td>存放不同环境配置的文件</td><td>以为改了 <code>.env</code> 会立刻生效。开发服务器需要重启</td><td><a href="/frontend-engineering-course/unit02/05-env-config.html">2.5</a></td></tr></tbody></table><h2 id="七、质量与协作" tabindex="-1">七、质量与协作 <a class="header-anchor" href="#七、质量与协作" aria-label="Permalink to &quot;七、质量与协作&quot;">​</a></h2><table tabindex="0"><thead><tr><th>术语（中英）</th><th>一句话解释</th><th>常见误解</th><th>出现位置</th></tr></thead><tbody><tr><td>代码规范 Lint</td><td>用工具检查代码里的潜在问题与风格问题</td><td>以为规范是&quot;为了好看&quot;。它拦住的是真实 bug</td><td><a href="/frontend-engineering-course/unit03/01-why-lint.html">3.1</a></td></tr><tr><td>提交规范 Commit Convention</td><td>约定提交信息的格式，如 <code>feat: 新增活动列表</code></td><td>以为格式只是形式。它是自动生成变更日志的依据</td><td><a href="/frontend-engineering-course/unit03/04-git-flow.html">3.4</a></td></tr><tr><td>代码评审 Code Review</td><td>提交前由他人检查改动</td><td>以为评审是挑错。它是知识传递和质量把关</td><td><a href="/frontend-engineering-course/unit03/04-git-flow.html">3.4</a></td></tr><tr><td>CI 流水线 CI Pipeline</td><td>每次提交后自动跑检查、构建、测试的流程</td><td>以为 CI 只在大公司用。一个小项目几百行配置就能跑起来</td><td><a href="/frontend-engineering-course/unit03/05-ci.html">3.5</a></td></tr><tr><td>单元测试 Unit Test</td><td>针对最小可测单元验证行为是否符合预期</td><td><strong>以为测试是为了证明代码没错</strong>。测试是为了在改动后快速发现&quot;改坏了什么&quot;</td><td><a href="/frontend-engineering-course/unit12/01-integration.html">12.1</a></td></tr><tr><td>快照测试 Snapshot Test</td><td>把输出结果存成基线，之后对比是否变化</td><td>以为快照变了就是 bug。有时是预期内的改动，要人工确认后更新基线</td><td><a href="/frontend-engineering-course/unit12/01-integration.html">12.1</a></td></tr><tr><td>声明式与命令式</td><td>声明式描述结果，命令式描述步骤</td><td>以为声明式一定更好。需要精细控制的地方仍要用命令式（如操作 DOM）</td><td><a href="/frontend-engineering-course/unit04/01-declarative.html">4.1</a></td></tr><tr><td>防抖 Debounce</td><td>事件停止触发一段时间后才执行</td><td>以为防抖能减少&quot;请求次数&quot;就够了。它也可能让用户觉得&quot;没反应&quot;</td><td><a href="/frontend-engineering-course/unit06/01-events.html">6.1</a></td></tr><tr><td>事件冒泡 Event Bubbling</td><td>事件从目标元素向上层元素传播</td><td>以为点了子元素父元素不会响应。默认会，需要 <code>.stop</code> 阻止</td><td><a href="/frontend-engineering-course/unit06/01-events.html">6.1</a></td></tr><tr><td>上下文丢失 this 指向</td><td>函数被单独取出后，原来的 <code>this</code> 不再生效</td><td>以为箭头函数能解决所有 <code>this</code> 问题。它反而会绑定外层 <code>this</code></td><td><a href="/frontend-engineering-course/unit07/03-emits.html">7.3</a></td></tr></tbody></table><h2 id="八、常见-看起来像-的概念对照" tabindex="-1">八、常见&quot;看起来像&quot;的概念对照 <a class="header-anchor" href="#八、常见-看起来像-的概念对照" aria-label="Permalink to &quot;八、常见&quot;看起来像&quot;的概念对照&quot;">​</a></h2><p>这几个概念对照最容易被混，单独列出来。</p><table tabindex="0"><thead><tr><th>一对概念</th><th>差别一句话</th></tr></thead><tbody><tr><td>打包 vs 压缩</td><td>打包是合并模块、处理依赖；压缩只是其中一步，去掉空格和缩短变量名</td></tr><tr><td>编译 vs 转译</td><td>编译是换语言（<code>.vue</code> 转 JS）；转译是同语言降版本（ES2022 转 ES2015）</td></tr><tr><td>构建 vs 部署</td><td>构建是把源码变成产物；部署是把产物放到服务器上让别人能访问</td></tr><tr><td>开发依赖 vs 运行时依赖</td><td>看&quot;打包后的运行时代码还需不需要它&quot;，需要就是运行时依赖</td></tr><tr><td><code>ref</code> vs <code>reactive</code></td><td>都能声明响应式状态；<code>ref</code> 通用且解构安全，<code>reactive</code> 适合整块对象</td></tr><tr><td><code>computed</code> vs <code>watch</code></td><td><code>computed</code> 算出一个值并缓存；<code>watch</code> 在变化时执行一段逻辑</td></tr><tr><td><code>computed</code> vs 普通函数</td><td><code>computed</code> 依赖不变就用缓存；普通函数每次调用都重算</td></tr><tr><td><code>params</code> vs <code>query</code></td><td><code>params</code> 是路径的一部分（<code>/activity/12</code>）；<code>query</code> 是问号后面（<code>?page=2</code>）</td></tr><tr><td><code>v-if</code> vs <code>v-show</code></td><td><code>v-if</code> 不生成节点；<code>v-show</code> 只切 <code>display</code>，适合频繁切换</td></tr><tr><td>props vs provide/inject</td><td>props 是父子逐层传；provide/inject 跳过中间层，但只在子树内存活</td></tr><tr><td>框架 vs 工程化</td><td>框架解决&quot;怎么写界面&quot;；工程化解决&quot;怎么让项目可维护、可协作、可交付&quot;</td></tr><tr><td>全局状态 vs 组件状态</td><td>判断依据是&quot;被不相邻的多个页面共用吗&quot;，不是&quot;这个数据重不重要&quot;</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">怎么用这张表</p><p>遇到分不清的概念，先在这张对照表里找。 <strong>如果找不到，说明它值得补充</strong> —— 记下来反馈给老师。</p><p>判断自己是不是真的分清了，有一个简单方法： <strong>能各举一个&quot;用了 A 而不是 B&quot;的具体场景，并且说出为什么。</strong> 只能复述定义，说明还没分清。</p></div><h2 id="九、跨端与小程序" tabindex="-1">九、跨端与小程序 <a class="header-anchor" href="#九、跨端与小程序" aria-label="Permalink to &quot;九、跨端与小程序&quot;">​</a></h2><p>做<a href="/frontend-engineering-course/mobile/">用户端</a>时会遇到这一组词。它们和后端的“多端”不是一回事， 说的是<strong>同一份前端代码怎么变成不同平台的应用</strong>。</p><table tabindex="0"><thead><tr><th>术语（中英）</th><th>一句话解释</th><th>常见误解</th><th>出现位置</th></tr></thead><tbody><tr><td>跨端框架 Cross-platform Framework</td><td>用一套代码生成多个平台应用的框架</td><td>以为“跨端”就是“自适应网页”。跨端产出的是真正的原生或小程序包，不是响应式布局</td><td><a href="/frontend-engineering-course/mobile/01-why-uniapp.html">1</a></td></tr><tr><td>uni-app</td><td>DCloud 出的跨端框架，编译到 H5、微信小程序、App 等多个平台</td><td>以为它是一个运行时库。它是<strong>编译器</strong>，产物里没有 uni-app 本身</td><td><a href="/frontend-engineering-course/mobile/01-why-uniapp.html">1</a></td></tr><tr><td>uni-app x</td><td>uni-app 的下一代，用 UTS 强类型语言，原生渲染</td><td>和经典版混为一谈。经典版用 JS/TS 走 WebView 混合渲染，生态完整；uni-app x 主攻 App 与鸿蒙，大量 JS npm 包不可用</td><td><a href="/frontend-engineering-course/mobile/01-why-uniapp.html">1</a></td></tr><tr><td>UTS</td><td>uni-app x 用的强类型语言，语法接近 TypeScript</td><td>以为是 TypeScript 的别名。它是编译到 Kotlin / Swift 的独立语言</td><td><a href="/frontend-engineering-course/mobile/01-why-uniapp.html">1</a></td></tr><tr><td>条件编译 Conditional Compilation</td><td>用特殊注释包住一段代码，让它只在某个平台编译进去</td><td>以为它是运行时判断。它在<strong>编译期</strong>就把别的平台的分支删掉了</td><td><a href="/frontend-engineering-course/mobile/04-layout-style.html">4</a></td></tr><tr><td>rpx</td><td>uni-app 的响应式单位，<strong>750rpx 永远等于屏幕宽度</strong></td><td>以为 rpx 是 px 的二分之一。它按屏幕宽度等比换算，与设备像素无关</td><td><a href="/frontend-engineering-course/mobile/04-layout-style.html">4</a></td></tr><tr><td>easycom</td><td>uni-app 的组件自动引入机制，按正则匹配组件路径</td><td>以为改完配置立刻生效。<code>pages.json</code> 的改动常常要重新编译</td><td><a href="/frontend-engineering-course/mobile/05-components.html">5</a></td></tr><tr><td>页面栈 Page Stack</td><td>当前打开的页面组成的栈，小程序最多 10 层</td><td>以为可以无限 <code>navigateTo</code>。超过 10 层会失败，要用 <code>redirectTo</code> 或 <code>reLaunch</code></td><td><a href="/frontend-engineering-course/mobile/03-pages-router.html">3</a></td></tr><tr><td>tabBar</td><td>底部导航栏，只能配 2 到 5 项</td><td>以为 tabBar 页面可以像普通页面一样 <code>navigateTo</code> 过去。它<strong>只能</strong>用 <code>switchTab</code>，而且不能带参数</td><td><a href="/frontend-engineering-course/mobile/03-pages-router.html">3</a></td></tr><tr><td>小程序 AppID</td><td>小程序的身份标识，写在 <code>manifest.json</code> 里</td><td>以为前端能拿 AppSecret。<strong>AppSecret 只能放在后端</strong>，泄露等于把整个小程序交出去</td><td><a href="/frontend-engineering-course/mobile/06-request-auth.html">6</a></td></tr><tr><td>code2session</td><td>后端拿 <code>code</code> 换 <code>openid</code> 的接口</td><td>以为前端可以直接调。它需要 AppSecret，<strong>必须由后端发起</strong></td><td><a href="/frontend-engineering-course/mobile/06-request-auth.html">6</a></td></tr><tr><td>Wot UI</td><td>手机端 UI 组件库，npm 包名是 <code>@wot-ui/ui</code></td><td>沿用旧包名 <code>wot-design-uni</code>。旧包已停更在 1.x</td><td><a href="/frontend-engineering-course/mobile/05-components.html">5</a></td></tr></tbody></table><h2 id="十、ai-协作" tabindex="-1">十、AI 协作 <a class="header-anchor" href="#十、ai-协作" aria-label="Permalink to &quot;十、AI 协作&quot;">​</a></h2><p>这一节的术语在 <a href="/frontend-engineering-course/guide/ai-coding.html">AI 编程导论</a> 之后出现得越来越频繁，不需要会实现，但要知道各自管什么。</p><table tabindex="0"><thead><tr><th>术语（中英）</th><th>一句话解释</th><th>常见误解</th><th>出现位置</th></tr></thead><tbody><tr><td>编码代理 Coding Agent</td><td>能读文件、改文件、跑命令的 AI 工具，不只是补全</td><td>以为它和代码补全是同一类。补全帮你打字，代理替你把事做完</td><td><a href="/frontend-engineering-course/guide/ai-coding.html">导论</a></td></tr><tr><td>上下文工程 Context Engineering</td><td>决定往对话里放哪些信息，让产出更准</td><td>以为提示词越长越好。无关信息会稀释重点</td><td><a href="/frontend-engineering-course/unit04/ai-collaboration.html">4</a></td></tr><tr><td>AGENTS.md</td><td>放在仓库根目录、写明项目约定的 Markdown 文件，供 AI 工具读取</td><td>以为它是某个工具的专有配置。它是跨工具的通用格式</td><td><a href="/frontend-engineering-course/unit03/ai-collaboration.html">3</a></td></tr><tr><td>渐进式披露 Progressive Disclosure</td><td>主文件只放导航性信息，细节按需展开</td><td>以为把全部内容塞进一个文件更好</td><td><a href="/frontend-engineering-course/unit03/ai-collaboration.html">3</a></td></tr><tr><td>规格驱动开发 Spec-Driven Development</td><td>先写清要建什么、为什么建，再让 AI 按规格实现</td><td>以为要多写一堆文档。需求、规则、接口这几份本身就是规格</td><td><a href="/frontend-engineering-course/unit11/ai-collaboration.html">11</a></td></tr><tr><td>MCP</td><td>让 AI 连接数据库、接口、内部系统等外部服务的一套协议</td><td>以为要自己实现。知道它是什么、什么时候需要就够</td><td><a href="/frontend-engineering-course/guide/ai-coding.html">导论</a></td></tr><tr><td>Agent Skills</td><td>把一套流程与参考资料打包成可复用的能力，AI 按需加载</td><td>以为要写代码。它就是一个目录加一份 Markdown</td><td><a href="/frontend-engineering-course/guide/ai-coding.html">导论</a></td></tr><tr><td>幻觉依赖 Hallucinated Dependency</td><td>AI 编出来的、仓库里不存在的包名或坐标</td><td>以为名字符合命名规范就一定是真的</td><td><a href="/frontend-engineering-course/unit02/ai-collaboration.html">2</a></td></tr><tr><td>提示注入 Prompt Injection</td><td>把恶意指令藏在 AI 会读到的地方，让它执行不该执行的操作</td><td>以为只和安全领域有关。2026 年 3 月已出现针对编码代理的真实攻击</td><td><a href="/frontend-engineering-course/guide/ai-coding.html">导论</a></td></tr><tr><td>验证缺口 Verification Gap</td><td>多数人知道 AI 代码不能全信，但不到一半的人每次提交前真的检查</td><td>以为看着跑通了就等于验证过</td><td><a href="/frontend-engineering-course/guide/ai-coding.html">导论</a></td></tr><tr><td>代码异味 Code Smell</td><td>不立即报错、但让代码越来越难维护的写法</td><td>以为只有报错的问题才算问题。有研究显示 AI 代码九成以上的问题属于这一类</td><td><a href="/frontend-engineering-course/unit12/ai-collaboration.html">12</a></td></tr></tbody></table><h3 id="两对容易混的" tabindex="-1">两对容易混的 <a class="header-anchor" href="#两对容易混的" aria-label="Permalink to &quot;两对容易混的&quot;">​</a></h3><table tabindex="0"><thead><tr><th>一对概念</th><th>差别一句话</th></tr></thead><tbody><tr><td>AI 补全 vs AI 代理</td><td>补全只在光标处给建议；代理会读文件、改多个文件、跑命令，自己完成任务</td></tr><tr><td>AGENTS.md vs CLAUDE.md</td><td>AGENTS.md 是跨工具通用的那个；CLAUDE.md 是 Claude Code 的原生格式，支持的配置项更多</td></tr></tbody></table><hr><p>上一节：<a href="/frontend-engineering-course/appendix/tools.html">工具链与版本清单</a> · 下一节：<a href="/frontend-engineering-course/appendix/ai-tools.html">AI 编程工具速查</a></p>',31)])])}const f=d(o,[["render",i]]);export{s as __pageData,f as default};
